export function makePrintHTML(svgOrURL,p,representation='vector'){
 const body=representation==='vector'?svgOrURL:`<img alt="Technical 3D figure" src="${svgOrURL}" style="width:100%;height:100%">`;
 return `<!doctype html><html><head><meta charset="utf-8"><title>Print technical figure</title><style>@page{size:${p.page.width_mm}mm ${p.page.height_mm}mm;margin:0}body{margin:0;background:#ddd;font:14px Arial}.sheet{width:${p.page.width_mm}mm;height:${p.page.height_mm}mm;background:white}.sheet>svg{display:block;width:100%;height:100%}nav{padding:12px}button{padding:10px}@media print{nav{display:none}body{background:white}.sheet{break-inside:avoid}}</style></head><body><nav><button onclick="window.print()">Print / Save as PDF</button> Print at 100%, no extra margins or headers. PDF geometry depends on the print dialog.</nav><main class="sheet">${body}</main></body></html>`;
}
